import { SiteNav } from "march/landing"
import { Card } from "march/ui"

// ruh hâli menüsü: bir bağlantıya basınca o hâl seçilir, hap üstünde durur ve aşağıdaki kart değişir
const MOODS = [
  { href: "#mood-sun", label: "Neşeli", face: "😄", text: "Bugün her şey yolunda." },
  { href: "#mood-tea", label: "Sakin", face: "🍵", text: "Bir çay, bir kitap." },
  { href: "#mood-fire", label: "Hırslı", face: "🔥", text: "Listeyi bitiriyoruz!" },
]

export function MoodNav() {
  let $mood = MOODS[0]!.href
  const current = () => MOODS.find((m) => m.href === $mood)!
  return <div sx={{ flex: "col", gap: 3 }}>
    <SiteNav mode="solid" sticky={false} brand={{ name: "Hâlim", mark: "🙂" }}
      links={MOODS.map((m) => ({ label: m.label, href: m.href, active: () => $mood === m.href }))}
      onNavigate={(href: string) => $mood = href} />
    <Card>
      {() => {
        const m = current()
        return <div id={m.href.slice(1)} sx={{ flex: ["row", "center"], gap: 3, p: 4 }}>
          <span sx={{ text: "2xl" }}>{m.face}</span>
          <strong>{m.text}</strong>
        </div>
      }}
    </Card>
  </div>
}

import { SiteNav } from "march/landing"
import { Button, toast } from "march/ui"
import { coffee, shoppingBag } from "march/icons"

// bir fırının sitesi: üstte yüzen menü, altta bölümler; bağlantılar bölüme kayar, geçerli bölüm işaretli
const SECTIONS = [
  { id: "firin-menu", label: "Menü", text: "Simit, poğaça, ekşi mayalı ekmek: her sabah 06.00'da fırından." },
  { id: "firin-subeler", label: "Şubeler", text: "Moda, Kadıköy ve Cihangir'de." },
  { id: "firin-hakkimizda", label: "Hakkımızda", text: "1974'ten beri aynı taş fırın." },
]

export function BakeryNav() {
  let $at = "#firin-menu"
  return <div sx={{ flex: "col", gap: 4 }}>
    <SiteNav mode="floating" brand={{ name: "Fırın Kemal", mark: coffee, sub: "1974" }} pillColor="brand-orange"
      links={SECTIONS.map((s) => ({ label: s.label, href: `#${s.id}`, active: () => $at === `#${s.id}` }))}
      onNavigate={(href: string) => $at = href}
      actions={<><Button variant="ghost" size="sm">Giriş</Button><Button size="sm" icon={shoppingBag} on:click={() => toast("Sepet açıldı")}>Sipariş ver</Button></>} />
    {SECTIONS.map((s) => <section id={s.id} sx={{ p: 4 }}>
      <h3>{s.label}</h3>
      <p sx={{ color: "muted" }}>{s.text}</p>
    </section>)}
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { SiteNavLab } from "./SiteNavLab.tsx"

// SiteNavLab'in testleri: kaydedince Testler sekmesinde çalışır
test("kendi adıyla bir gezinme; geçerli sayfa işaretli", () => {
  const s = renderTest(() => <SiteNavLab />)
  expect(s.get("header.lab-nav")?.classList.contains("m-snav-floating")).toBe(true)
  expect(s.get('nav[aria-label="Site"]')).not.toBe(null)
  expect(s.get('a[aria-current="page"]')?.textContent).toBe("Keşfet")
})

test("bir bağlantıya basınca geçerli sayfa değişir", async () => {
  const s = renderTest(() => <SiteNavLab />)
  await s.click(s.get('a[href="#lab-blog"]')!)
  expect(s.get('a[aria-current="page"]')?.textContent).toBe("Blog")
  expect(s.sees("Seçili sayfa: #lab-blog")).toBe(true)
})

test("eylem düğmesi sayar", async () => {
  const s = renderTest(() => <SiteNavLab />)
  await s.click("Katıl (0)")
  expect(s.find("Katıl (1)")).not.toBe(null)
})

test("hap ve menü düğmesi anahtarlarla kapanır", async () => {
  const s = renderTest(() => <SiteNavLab />)
  expect(s.get(".m-snav-pill")).not.toBe(null)
  expect(s.get('[aria-label="Menüyü göster"]')).not.toBe(null)
  await s.click("Hap")
  await s.click("Menü düğmesi")
  expect(s.get(".m-snav-pill")).toBe(null)
  expect(s.get('[aria-label="Menüyü göster"]')).toBe(null)
})
